function getManeuverInfo(step){
  const m=step?.maneuver||{},type=m.type||'',mod=m.modifier||'',road=step?.name?`نحو ${step.name}`:'';
  let icon='↑',text='واصل السير للأمام';
  if(type==='depart'){icon='▲';text=step?.name?`انطلق باتجاه ${step.name}`:'انطلق من نقطة البداية';}
  else if(type==='arrive'){icon='🏁';text='ستصل إلى وجهتك المباركة';}
  else if(mod==='sharp left'){icon='⮣';text=`انعطاف حاد يساراً ${road}`.trim();}
  else if(mod==='left'){icon='↰';text=`انعطف يساراً ${road}`.trim();}
  else if(mod==='slight left'){icon='⤾';text=`انحرف يساراً قليلاً ${road}`.trim();}
  else if(mod==='sharp right'){icon='⮥';text=`انعطاف حاد يميناً ${road}`.trim();}
  else if(mod==='right'){icon='↱';text=`انعطف يميناً ${road}`.trim();}
  else if(mod==='slight right'){icon='⤿';text=`انحرف يميناً قليلاً ${road}`.trim();}
  else if(mod==='uturn'){icon='⮌';text='استدر وعُد إلى الاتجاه المعاكس';}
  else if(type==='roundabout'){icon='⭯';text=`ادخل الدوار ${road}`.trim();}
  else{icon='↑';text=step?.name?`واصل السير على ${step.name}`:'واصل السير للأمام';}
  const distText=step?.distance>999?`${(step.distance/1000).toFixed(1)} كم`:`في ${Math.round(step?.distance||0)} م`;
  return {icon,text,distText,road:step?.name||'شارع بدون اسم'};
}

function speakWaze(text){
  if(!wazeVoiceEnabled||!('speechSynthesis' in window))return;
  try{
    window.speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(text);
    u.lang=lang==='en'?'en-US':lang==='fa'?'fa-IR':'ar-IQ';
    u.rate=0.95;
    window.speechSynthesis.speak(u);
  }catch{}
}

function updateWazeHud(stepIndex=0){
  if(!currentRouteSteps.length)return;
  currentStepIndex=Math.min(stepIndex,currentRouteSteps.length-1);
  const step=currentRouteSteps[currentStepIndex],nextStep=currentRouteSteps[currentStepIndex+1];
  const info=getManeuverInfo(step),nextInfo=nextStep?getManeuverInfo(nextStep):null;
  const hud=$('wazeGuidanceHud');
  if(hud){
    hud.hidden=false;
    $('wazeManeuverIcon').textContent=info.icon;
    $('wazeNextDistance').textContent=info.distText;
    $('wazeStreetName').textContent=info.text;
    $('wazeNextInstruction').textContent=nextInfo?`ثم ${nextInfo.text}`:'نهاية المسار';
  }
  const etaBar=$('wazeEtaBar');
  if(etaBar&&currentRouteData){
    etaBar.hidden=false;
    $('wazeEtaDuration').textContent=Math.ceil(currentRouteData.duration/60);
    $('wazeEtaDistance').textContent=`${(currentRouteData.distance/1000).toFixed(1)} كم`;
    const arrTime=new Date(Date.now()+currentRouteData.duration*1000);
    const loc=lang==='en'?'en-US':lang==='fa'?'fa-IR':'ar-IQ';
    $('wazeEtaClock').textContent=`الوصول: ${arrTime.toLocaleTimeString(loc,{hour:'2-digit',minute:'2-digit'})}`;
  }
}

function renderWazeRouteAlerts(coords){
  wazeHazardMarkers.forEach(m=>map?.removeLayer(m));
  wazeHazardMarkers=[];
  if(!coords||coords.length<3)return;
  const savedReports=read('waze-reports');
  const sampleIndices=[Math.floor(coords.length*0.25),Math.floor(coords.length*0.55),Math.floor(coords.length*0.8)];
  const defaultAlerts=[
    {type:'water',note:'توزيع ماء شرب بارد وعصائر للزوار'},
    {type:'mawkeeb',note:'موكب خدمة وضيافة زوار الحسين (ع)'},
    {type:'clinic',note:'مفرزة إسعاف ومفارز طوارئ ميدانية'}
  ];
  const list=[
    ...defaultAlerts.map((a,i)=>({
      ...a,
      lat:coords[sampleIndices[i]][1],
      lng:coords[sampleIndices[i]][0]
    })),
    ...savedReports
  ];
  list.forEach(alert=>{
    if(!coord(alert.lat,alert.lng))return;
    const meta=WAZE_HAZARDS[alert.type]||WAZE_HAZARDS.water;
    const alertIcon=L.divIcon({
      className:'waze-hazard-leaflet-icon',
      html:`<div class="waze-map-hazard-badge" style="background:${meta.color}" title="${esc(meta.title)}"><span>${meta.icon}</span></div>`,
      iconSize:[34,34],
      iconAnchor:[17,17]
    });
    const m=L.marker([alert.lat,alert.lng],{icon:alertIcon})
      .bindPopup(`<div class="waze-hazard-popup"><b style="color:${meta.color}">${meta.icon} ${esc(meta.title)}</b><p>${esc(alert.note||'تنبيه ميداني مباشر كـ Waze')}</p><small>إبلاغ مجتمعي لزوار الحسين</small></div>`)
      .addTo(map);
    wazeHazardMarkers.push(m);
  });
}

function startNavigation(){
  if(!currentRouteData||!currentRouteSteps.length){toast('يرجى حساب مسار أولاً لبدء الملاحة');return;}
  isNavigating=true;
  $('wazeStartNavBtn')?.classList.add('navigating');
  if($('wazeNavBtnText'))$('wazeNavBtnText').textContent='إنهاء الملاحة';
  const coords=currentRouteData.geometry.coordinates;
  let coordIndex=0;
  const navIcon=L.divIcon({
    className:'waze-nav-cursor-icon',
    html:'<div class="waze-nav-arrow-cursor"><div class="waze-pulse-ring"></div><div class="waze-chevron-core">▲</div></div>',
    iconSize:[40,40],
    iconAnchor:[20,20]
  });
  if(navMarker)map.removeLayer(navMarker);
  const startPt=[coords[0][1],coords[0][0]];
  navMarker=L.marker(startPt,{icon:navIcon,zIndexOffset:1000}).addTo(map);
  map.flyTo(startPt,17,{animate:true,duration:1});
  updateWazeHud(0);
  speakWaze(`بدء الملاحة المباشرة. ${getManeuverInfo(currentRouteSteps[0]).text}`);
  toast('بدأت الملاحة التفاعلية كـ Waze');
  clearInterval(navSimTimer);
  navSimTimer=setInterval(()=>{
    coordIndex++;
    if(coordIndex>=coords.length){
      stopNavigation();
      speakWaze('لقد وصلت إلى وجهتك المباركة، نسأل الله قبول الزيارة');
      toast('🏁 وصلت إلى وجهتك المباركة!');
      return;
    }
    const curPt=[coords[coordIndex][1],coords[coordIndex][0]];
    navMarker.setLatLng(curPt);
    map.panTo(curPt,{animate:true,duration:0.8});
    if(currentStepIndex<currentRouteSteps.length-1){
      const nextStepLoc=currentRouteSteps[currentStepIndex+1].maneuver.location;
      const dLat=curPt[0]-nextStepLoc[1],dLng=curPt[1]-nextStepLoc[0];
      if(Math.hypot(dLat,dLng)<0.001){
        currentStepIndex++;
        updateWazeHud(currentStepIndex);
        speakWaze(getManeuverInfo(currentRouteSteps[currentStepIndex]).text);
      }
    }
  },1800);
}

function stopNavigation(){
  isNavigating=false;
  clearInterval(navSimTimer);
  navSimTimer=null;
  if(navMarker){map?.removeLayer(navMarker);navMarker=null;}
  $('wazeStartNavBtn')?.classList.remove('navigating');
  if($('wazeNavBtnText'))$('wazeNavBtnText').textContent='بدء الملاحة';
}

