async function setupAI(){const c=window.HALA_CONFIG||{},setLocalStatus=()=>{$('assistantConnection').textContent=lang==='en'?'Local assistant · knowledge stored on this device':lang==='fa'?'راهنمای محلی':'مساعد محلي يعمل على هذا الجهاز';$('assistantIntro').textContent=lang==='en'?'Ask about this guide, its map, and the information listed here. Answers use the local guide only.':lang==='fa'?'پرسش درباره راهنما و نقشه':'أجب عن أسئلة الدليل والخريطة من المعرفة المحلية المتوفرة فقط.';$('assistantDisclosure').textContent=lang==='en'?'Questions are processed on this device and are not sent to an AI service.':lang==='fa'?'پرسش‌ها به‌صورت محلی پردازش می‌شوند.':'تُحلل الأسئلة محلياً على هذا الجهاز ولا تُرسل إلى خدمة ذكاء اصطناعي خارجية.'};setLocalStatus();if(!c.supabaseUrl||!c.supabaseAnonKey||!window.supabase?.createClient)return;try{accountClient=window.HalaSupabase?.getClient();if(!accountClient)return;void syncDatabaseData();const {data,error}=await accountClient.auth.getSession();if(error)throw error;if(!data.session){const result=await accountClient.auth.signInAnonymously();if(result.error)throw result.error}void syncDatabaseData();if(!window.halaAuthListener)window.halaAuthListener=accountClient.auth.onAuthStateChange((event,session)=>{setTimeout(()=>{void syncDatabaseData();if(!session)void setupAI()},0)})}catch{$('assistantConnection').textContent=lang==='en'?'Local assistant · offline site data unavailable':'مساعد محلي · بيانات الموقع غير متصلة'}}function renderBookings(rows=[]){const root=$('bookingList');if(!root)return;if(!currentUser||currentUser.is_anonymous){root.innerHTML=`<div class="info-banner"><span>${esc(t('bookingAccountHint'))}</span></div>`;return}const filter=document.querySelector('[data-booking-filter].selected')?.dataset.bookingFilter||'current';const relevant=rows.filter(r=>filter==='current'?['pending','confirmed','checked_in'].includes(r.status):filter==='past'?['completed'].includes(r.status):['cancelled','rejected'].includes(r.status));root.innerHTML=relevant.length?relevant.map(r=>{const place=allPlaces().find(p=>p.id===r.location_id),isHost=place?.host_id===currentUser.id;return `<article class="booking-card"><div><b>${esc(place?.name||r.booking_code)}</b><small>${new Date(r.starts_at).toLocaleDateString()} – ${new Date(r.ends_at).toLocaleDateString()} · ${esc(r.status)} · ${r.guest_count}</small></div>${isHost&&r.status==='pending'?`<button class="text-button" data-manage-booking="confirmed" data-booking-id="${esc(r.id)}">قبول</button><button class="text-button" data-manage-booking="rejected" data-booking-id="${esc(r.id)}">رفض</button>`:''}${!isHost&&r.visitor_id===currentUser.id&&['pending','confirmed'].includes(r.status)?`<button class="text-button" data-cancel-booking="${esc(r.id)}">${lang==='en'?'Cancel':'إلغاء'}</button>`:''}</article>`}).join(''):`<div class="empty-panel"><p>${esc(t('noBookings'))}</p></div>`}async function refreshBookings(){if(!currentUser||currentUser.is_anonymous){renderBookings();return}try{renderBookings(await window.HalaData.bookings(accountClient,remotePlaces.filter(p=>p.host_id===currentUser.id).map(p=>p.id)))}catch{const root=$('bookingList');if(root)root.textContent=lang==='en'?'Bookings could not be loaded.':'تعذر تحميل الحجوزات.'}}
function openBookingForm(locationId){if(!currentUser||currentUser.is_anonymous){account('signin');toast(lang==='en'?'Sign in before booking':'سجل الدخول قبل إرسال طلب الحجز');return}const place=remotePlaces.find(p=>p.id===locationId);if(!place)return;let start=new Date(Date.now()+86400000),end=new Date(Date.now()+172800000);const localValue=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);modal(lang==='en'?'Request accommodation':'طلب استضافة',place.name,`<form class="modal-form" id="bookingForm"><label>${lang==='en'?'Arrival':'تاريخ الوصول'}<input id="bookingStart" type="datetime-local" value="${localValue(start)}" required></label><label>${lang==='en'?'Departure':'تاريخ المغادرة'}<input id="bookingEnd" type="datetime-local" value="${localValue(end)}" required></label><label>${lang==='en'?'Guests':'عدد الضيوف'}<input id="bookingGuests" type="number" min="1" max="30" value="1" required></label><label>${lang==='en'?'Notes':'ملاحظات'}<textarea id="bookingNotes" maxlength="1000"></textarea></label><button class="btn btn-green">${lang==='en'?'Send request':'إرسال الطلب'}</button></form>`);$('bookingForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{await window.HalaData.createBooking(accountClient,{p_location_id:locationId,p_guest_count:+$('bookingGuests').value,p_starts_at:new Date($('bookingStart').value).toISOString(),p_ends_at:new Date($('bookingEnd').value).toISOString(),p_notes:$('bookingNotes').value.trim()});closeModal();toast(lang==='en'?'Booking request sent':'تم إرسال طلب الحجز');await syncDatabaseData();await refreshBookings()}catch{toast(lang==='en'?'The place may no longer have enough capacity. Refresh and try again.':'قد لا تتوفر سعة كافية الآن. حدّث البيانات وحاول مجدداً')}finally{button.disabled=false}}}
async function showNotifications(){if(!currentUser||currentUser.is_anonymous){account('signin');return}try{const list=await window.HalaData.notifications(accountClient);const items=list.map(n=>{const readButton=n.read_at?'':`<button class="text-button" data-read-notification="${esc(n.id)}">${lang==='en'?'Mark read':'تحديد كمقروء'}</button>`;return `<article class="notification-item" data-notification="${esc(n.id)}"><b>${esc(n.title)}</b><p>${esc(n.body)}</p><small>${new Date(n.created_at).toLocaleString()}</small>${readButton}</article>`}).join('');const html=list.length?`<div class="notification-list">${items}</div>`:`<p>${lang==='en'?'No notifications':'لا توجد إشعارات'}</p>`;modal(lang==='en'?'Notifications':'الإشعارات','',html)}catch{toast(lang==='en'?'Could not load notifications':'تعذر تحميل الإشعارات')}}async function refreshNotificationCount(){if(!currentUser||currentUser.is_anonymous)return;try{const count=await window.HalaData.unreadNotificationCount(accountClient);const b=$('notifyBtn');if(b)b.dataset.unread=count?String(count):''}catch{}}
function openEditListing(id){const p=remotePlaces.find(x=>x.id===id);if(!p||p.host_id!==currentUser?.id)return;modal('تعديل مكان الاستضافة',p.name,`<form class="modal-form" id="editListingForm"><label>اسم المكان<input id="editListingName" maxlength="120" value="${esc(p.name)}" required></label><label>العنوان<input id="editListingAddress" maxlength="240" value="${esc(p.address||'')}"></label><label>الوصف<textarea id="editListingDescription" maxlength="1200">${esc(p.description||'')}</textarea></label><div class="form-row"><label>السعة الإجمالية<input id="editListingTotal" type="number" min="0" max="500" value="${Number.isFinite(+p.capacity)?+p.capacity:0}" required></label><label>الأماكن المتاحة<input id="editListingCapacity" type="number" min="0" max="500" value="${Number.isFinite(+p.available)?+p.available:0}" required></label></div><button class="btn btn-green">حفظ التعديلات</button></form>`);$('editListingForm').onsubmit=async e=>{e.preventDefault();const total=+$('editListingTotal').value,available=+$('editListingCapacity').value;if(available>total){toast('الأماكن المتاحة لا يمكن أن تتجاوز السعة الإجمالية');return}try{await window.HalaData.updateLocation(accountClient,id,{name:$('editListingName').value.trim(),address:$('editListingAddress').value.trim(),description:$('editListingDescription').value.trim()});await window.HalaData.setCapacity(accountClient,id,total,available);closeModal();toast('تم حفظ التعديلات');await syncDatabaseData()}catch{toast('تعذر الحفظ؛ تحقق من عدم خفض السعة عن الحجوزات النشطة')}}}async function deleteListing(id){const p=remotePlaces.find(x=>x.id===id);if(!p||p.host_id!==currentUser?.id)return;if(!confirm('حذف مكان الاستضافة؟'))return;try{await window.HalaData.deleteLocation(accountClient,id);if(p.image_path)if(p.image_path)await window.HalaData.removeAccommodationImage(accountClient,p.image_path).catch(()=>{});toast('تم حذف المكان');await syncDatabaseData()}catch{toast('لا يمكن حذف المكان لوجود حجوزات نشطة أو لعدم توفر الصلاحية')}}asyn